insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('a-kuaza-schnoiza-mit-da-zungan-und-olle-san-kusch', 'A kuaza Schnoiza mit da Zungan - und olle san kusch!', '', '', '', 'Wiener Gaunersprache', 'Ein kurzer Schnalzer mit der Zunge - und alle sind kusch!', '[{"kategorie": "wörtlich", "text": "\"Ein kurzer Zungenschnalzer - und keiner muckt mehr!\"  2. \"Ein kurzer Zungenschnalzer, und alle parieren!\"  3. \"Wenn der Boss kurz mit der Zunge schnalzt, sind alle still und handzahm!\""}]'::jsonb, ''),
  ('da-schuss-aus-seina-pistoin-hod-ned-dumpf-klungan-eeha-wiara-hoella-schnoiza', 'Da Schuss aus seina Pistoin hod ned dumpf klungan - eeha wiara hölla Schnoiza!', '', '', '', 'Wiener Gaunersprache', 'Der Schuss aus seiner Pistole hat nicht dumpf geklungen - eher wie ein heller Schnalzer!', '[{"kategorie": "wörtlich", "text": "\"Der Schuss aus seiner Pistole klang nicht dumpf - eher wie ein knackiger Schlag!\"  2. \"Das war kein dumpfer Knall – der Schuss aus seiner Pistole klang hell und scharf!\"  3. \"Der Schuss aus seiner Pistole war alles andere als dumpf - er klang hell und knackend, fast peitschenartig!\""}]'::jsonb, ''),
  ('a-laechln-a-haundschloog-und-da-schnoiza-hod-di-schoo-eigsaafd', 'A Lächln, a Haundschloog - und da Schnoiza hod di schoo eigsaafd!', '', '', '', 'Wiener Gaunersprache', 'Ein Lächeln, ein Handschlag - und der Schnalzer hat dich schon eingeseift!', '[{"kategorie": "wörtlich", "text": "\"Ein Grinsen, ein Händedruck – und dieser Trickser hat dich schon übers Ohr gehauen!\"  2. \"Ein Lächeln, ein Handschlag - und dieser Betrüger hat dich im Netz!\"  3. \"So schnell kannst du gar nicht schauen, hat dich dieses Schlitzohr auch schon reingedreht!\""}]'::jsonb, ''),
  ('nooch-dem-schnoiza-is-kloa-wo-ma-schdee', 'Nooch dem Schnoiza is kloa, wo ma schdee!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Nach diesem Schnalzer ist klar, wo wir stehen!', '[{"kategorie": "wörtlich", "text": "\"Nach dieser Niederlage ist klar, wo wir stehen!\"  2. \"Spätestens nach dieser Pleite weiß jeder, wo wir stehen!\"  3. \"So ein Schnalzer zeigt dir gnadenlos, wo du mit deiner Mannschaft stehst!\""}]'::jsonb, ''),
  ('friara-haums-de-bluadhund-looslossn-ois-waarad-da-mensch-freiwueued', 'Friara haums de Bluadhund looslossn, ois waarad da Mensch Freiwüüd!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher haben sie die Bluthunde losgelassen, als wäre der Mensch Freiwild!', '[{"kategorie": "wörtlich, hist.", "text": "\"Sie ließen einst die Bluthunde los, als wäre der Mensch nur noch Freiwild!\"  2. \"Einst hetzten sie die Bluthunde auf die Menschen, als wären diese nur noch Jagdbeute!\"  3. \"Damals wurde der Mensch gejagt wie Freiwild, mit Bluthunden im Rücken!\""}]'::jsonb, ''),
  ('waunnsd-amoi-im-visiia-von-de-bluadhund-bist-kummsd-nimma-ausse', 'Waunnsd amoi im Visiia von de Bluadhund bist, kummsd nimma ausse!', '', '', '', 'Wiener Gaunersprache', 'Wenn du einmal im Visier der Bluthunde bist, kommst du nicht mehr raus!', '[{"kategorie": "wörtlich", "text": "\"Einmal im Visier der Bluthunde, kommt man nicht mehr raus!\"  2. \"Wer einmal im Visier dieser skrupellosen Vollstrecker ist, entkommt ihnen nicht mehr!\"  3. \"Haben dich die Bluthunde erst mal gewittert, lassen sie von dir nicht mehr ab!\""}]'::jsonb, ''),
  ('waunns-eanst-wiad-schickns-in-schoafn-in-mau-fias-groobe', 'Waunns eanst wiad, schickns in Schoafn - in Mau fias Groobe!', '', '', '', 'Wiener Gaunersprache', 'Wenn’s ernst wird, schicken sie den Scharfen - den Mann fürs Grobe!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Wenn’s ernst wird, schicken sie den Vollstrecker - den Mann fürs Grobe!\"  2. \"Wird''s heikel, lassen sie den Prügelknecht von der Leine!\"  3. \"Wenn''s dreckig wird, schicken sie den Bluthund - den Mann fürs Grobe!\""}]'::jsonb, ''),
  ('de-scheewaln-miassn-luftich-sei-und-diafn-ned-zafoin', 'De Scheewaln miassn luftich sei und diafn ned zafoin!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Schöberln müssen luftig sein und dürfen nicht zerfallen!', '[{"kategorie": "wörtlich", "text": "\"Die Eierbiskuitwürfel sollen schön locker sein und dürfen nicht auseinanderfallen!\"  2. \"Eierschöberln als Suppeneinlage sind luftig auszubacken und dürfen nicht zerbröseln!\"  3. \"Die Schöberln müssen schön aufgehen und Form halten!\""}]'::jsonb, ''),
  ('a-gscheide-scheewalsuppn-muass-soo-sei-dassd-min-leffae-wos-dawischd', 'A gscheide Scheewalsuppn muass soo sei, dassd min Leffä wos dawischd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine g''scheite Schöberlsuppe muss so sein, dass du mit''m Löffel was erwischt!', '[{"kategorie": "wörtlich", "text": "\"Eine anständige Schöberlsuppe erkennt man daran, dass der Löffel was erwischt!\"  2. \"Bei einer ordentlichen Schöberlsuppe fischst du mit dem Löffel immer was raus!\"  3. \"Wenn der Löffel nix erwischt, ist''s keine Schöberlsuppe, sondern eine Schmähbrühe!\""}]'::jsonb, ''),
  ('kaisascheewaln-miassn-bsundas-fein-ausboochn-sei-und-diafn-easchd-kuaz-vuam-seawiian-ind-suppn-geebm-wean', 'Kaisascheewaln miassn bsundas fein ausboochn sei und diafn easchd kuaz vuam Seawiian ind Suppn geebm wean!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Kaiserschöberl sind besonders fein auszubacken und erst kurz vor dem Servieren in die Suppe zu geben!', '[{"kategorie": "wörtlich", "text": "\"Kaiserschöberl sind besonders fein auszubacken und erst kurz vor dem Servieren in die Suppe zu geben!\"  2. \"Kaiserschöberl werden sehr fein gebacken und erst unmittelbar vor dem Anrichten zur Suppe gegeben!\"  3. \"Die Kaiserschöberl fein-luftig ausbacken nicht zu früh einlegen, sonst werden sie [[letschert]]!\""}]'::jsonb, ''),
  ('putz-di-scheewal', 'Putz di, Scheewal!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Putz dich, Schöberl!', '[{"kategorie": "wörtlich", "text": "\"Verschwinde, Schöberl!\" ([[Schöberl]] steht hier metaphorisch für etwas Kleines, Luftiges, Wegzuschöpfendes –\nund wird deshalb ideal als spöttische Personenabwertung verwendet)"}, {"kategorie": "", "text": "\"Hau ab, du [[Heini]]!  3. Zieh Leine, du [[Dillo]]!  4. Mach dich vom Acker, du [[Koffer]]!  5. \"Moch an Schuach, du Wappla!\""}]'::jsonb, 'Moch an Schuach, du Wappla!'),
  ('moch-an-schuach-du-wappla', 'Moch an Schuach, du Wappla!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Mach ''nen Schuh, du Wappler!', '[{"kategorie": "wörtlich", "text": "\"Verschwinde, du Armleuchter!\"  2. \"Hau ab, du Pfeife!  3. Zieh Leine, du [[Dillo]]!  4. Mach dich vom Acker, du [[Koffer]]!  5. [[Putz di, Scheewal!]]"}]'::jsonb, ''),
  ('heeb-di-scheewal-sunst-bleibst-a-doikn', 'Heeb di Scheewal, sunst bleibst a Doikn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Hebe dich, Schöberl, sonst bleibst du ein Dalken!', '[{"kategorie": "wörtlich", "text": "\"Beweg dich, du Knödel, sonst bleibst du am Ende noch sitzen wie ein nicht aufgegangener Teig!\"  2. Heb deinen Hintern in die Höh und setz dich endlich in Bewegung!  3. (fig.) Bleib nicht sitzen, sondern mach endlich den ersten Schritt!"}]'::jsonb, ''),
  ('ria-di-laawal-sunst-bleibst-a-doikn', 'Ria di Laawal, sunst bleibst a Doikn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Rühre dich, Laberl, sonst bleibst du ein Dalken!', '[{"kategorie": "wörtlich", "text": "\"Beweg dich, du Knödel, sonst bleibst du noch sitzen wie ein nicht aufgegangener Teig!\"  2. Heb deinen Hintern in die Höh und setz dich endlich in Bewegung!  3. (fig.) Bleib nicht sitzen, sondern mach endlich den ersten Schritt!"}]'::jsonb, ''),
  ('da-wind-is-in-schoowa-einegfoan-und-hods-trockane-hei-davootroong', 'Da Wind is in Schoowa einegfoan und hods trockane Hei davootroong!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Wind ist in den Schober hineingefahren und hat das trockene Heu davongetragen!', '[{"kategorie": "wörtlich", "text": "\"Der Wind fuhr durch den Schober und trug das trockene Heu davon!\"  2. \"Der Wind fegte durch den Strohhaufen und blies das trockene Heu davon!\"  3. \"Der Wind riss den Schober entzwei und verteilte das trockene Heu über das gesamte Feld!\""}]'::jsonb, ''),
  ('noochn-oidn-mooss-entschbrichd-a-schoowa-sechzg-bundane-gaarbn-schdroo', 'Noochn oidn Mooss entschbrichd a Schoowa sechzg bundane Gaarbn Schdroo!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Nach altem Maß entspricht ein Schober sechzig gebundenen Garben Stroh!', '[{"kategorie": "wörtlich", "text": "\"Ein Schober gilt nach altem Maß für sechzig gebundene Garben Stroh!\"  2. \"Nach der alten Maßordnung umfasst ein Schober sechzig Garben Stroh!\"  3. \"Ein Schober wird nach altem und gemeinem Maß auf sechzig gebundene Garben Stroh gerechnet!\""}]'::jsonb, ''),
  ('im-schoowa-wean-hei-und-koan-noch-oida-sitte-getrennt-gloogad', 'Im Schoowa wean Hei und Koan noch oida Sitte getrennt gloogad!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Im Schober werden Heu und Korn nach alter Sitte getrennt gelagert!', '[{"kategorie": "wörtlich", "text": "\"Im Schober werden Heu und Korn nach altem Brauch getrennt verwahrt!\"  2. \"Heu und Getreide lagern im Stadel nach althergebrachter Ordnung strikt getrennt voneinander!\"  3. \"Nach alter Sitte sind in der Feldscheune Heu und Korn stets getrennt aufgeschichtet!\""}]'::jsonb, ''),
  ('i-sitz-auf-an-schoowa-von-aktn', 'I sitz auf an Schoowa von Aktn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Ich sitze auf einem Schober von Akten!', '[{"kategorie": "wörtlich", "text": "\"Ich sitze auf einem Berg von Akten!\"  2. \"Ich versinke in einem riesigen Aktenhaufen!\"  3. \"Der Aktenstapel wächst mir brutal über den Kopf!\""}]'::jsonb, ''),
  ('fia-gleichmaeaessiche-scheibm-wiads-schopfbraadl-quea-zua-faasa-gschniidn', 'Fia gleichmäässiche Scheibm wiads Schopfbraadl quea zua Faasa gschniidn!', '', '', '', 'Wiener Fleischhauer-Slang', 'Für gleichmäßige Scheiben wird das Schopfbratl quer zur Faser geschnitten!', '[{"kategorie": "wörtlich", "text": "\"Für gleichmäßige Scheiben wird der Schopfbraten quer zur Faser geschnitten!\"  2. \"Damit die Scheiben schön gleichmäßig werden, schneidet man den Schopfbraten quer zur Faser!\"  3. \"Gegen die Faser geschnitten, lässt sich der Schopfbraten scheibchenweise besser portionieren!\""}]'::jsonb, ''),
  ('a-schepsanes-brauchd-zeit-daunn-wiads-mueab-und-aromatisch', 'A Schepsanes brauchd Zeit - daunn wiads müab und aromatisch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Schöpsernes braucht Zeit, dann wird es mürbe und aromatisch!', '[{"kategorie": "wörtlich", "text": "\"Hammelfleisch braucht Zeit, dann wird es mürbe und aromatisch!\"  2. \"Schöpsernes muss lange garen, dann wird es zart und geschmackvoll!\"  3. \"Hammelfleisch gewinnt durch schonendes Schmoren sowohl an Zartheit als auch an Geschmack!\""}]'::jsonb, ''),
  ('es-schepsnfleisch-kummd-vom-kastriadn-haummae-und-is-dunkla-und-festa-ois-laummfleisch', 'Es Schepsnfleisch kummd vom kastriadn Haummä und is dunkla und festa ois Laummfleisch!', '', '', '', 'Wiener Fleischhauer-Slang', 'Das Schöpsenfleisch kommt vom kastrierten Hammel und ist dunkler und fester als Lammfleisch!', '[{"kategorie": "wörtlich", "text": "\"Das [[Schöpserne]] stammt vom kastrierten Hammel und ist dunkler und fester als Lammfleisch!\"  2. \"Hammelfleisch stammt vom kastrierten Schafbock und unterscheidet sich durch dunklere Farbe und festere Struktur vom Lammfleisch!\"  3. \"Aufgrund des Alters und der Kastration ist Schöpsenfleisch dunkler und fester als Lamm!\""}]'::jsonb, ''),
  ('da-scheps-is-a-kastriiada-schofbock-ea-liifad-a-fests-fleisch-des-owa-gscheid-gwiazd-wean-muass', 'Da Scheps is a kastriiada Schofbock - ea liifad a fests Fleisch, des owa gscheid gwiazd wean muass!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Der Schöps ist ein kastrierter Schafbock - er liefert festes Fleisch, das aber stark gewürzt werden muss!', '[{"kategorie": "wörtlich", "text": "\"Der Schöps, ein kastrierter Schafbock, liefert ein festes, stark gewürzbedürftiges Fleisch!\"  2. \"Der Schöps ist ein kastrierter Hammel und liefert festes Fleisch, das aber nach kräftiger Würzung verlangt!\"  3. \"Schöpsfleisch, gewonnen vom kastrierten Schafbock, ist fest und benötigt eine intensive Würzung!\""}]'::jsonb, ''),
  ('a-scheps-is-a-vaschniidana-schoofbock-und-deaf-ned-ois-laummfleisch-vakaufd-wean', 'A Scheps is a vaschniidana Schoofbock und deaf ned ois Laummfleisch vakaufd wean!', '', '', '', 'Wiener Fleischhauer-Slang', 'Ein Schöps ist ein verschnittener Schafbock und darf nicht als Lammfleisch verkauft werden!', '[{"kategorie": "wörtlich", "text": "\"Der Schöps ist ein kastrierter Schafbock und darf nicht als Lammfleisch geführt oder verkauft werden!\"  2. \"Schöpsfleisch stammt vom verschnittenen Bock und darf nicht als Lamm deklariert werden!\"  3. \"Schöpsenfleisch unterliegt der Kennzeichnung als Hammelfleisch und darf nicht als Lammfleisch verkauft werden!\""}]'::jsonb, ''),
  ('dea-hod-a-gschau-wiara-scheps-dea-grood-kastriad-wiad', 'Dea hod a Gschau wiara Scheps, dea grood kastriad wiad!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat ein Gschau wie ein Schöps, der gerade kastriert wird!', '[{"kategorie": "wörtlich", "text": "\"Der schaut drein wie ein Hammel, der gerade kastriert wird!\"  2. \"Der blöde Hammel macht ein Gesicht, als würde er gerade kastriert!\"  3. \"Dieser Depp zieht eine Miene wie ein Schöps bei der Kastration!"}]'::jsonb, ''),
  ('da-schepsnschleegl-wiad-gsoizn-mit-zwiifaen-in-fett-augsetzd-und-zuadeckd-saunft-dinsted', 'Da Schepsnschleegl wiad gsoizn, mit Zwiifän in Fett augsetzd und zuadeckd saunft dinsted!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Schöpsenschlögel wird gesalzen, mit Zwiebeln in Fett angesetzt und zugedeckt sanft gedünstet!', '[{"kategorie": "wörtlich", "text": "\"Der gesalzene Hammelschlögel kommt mit Zwiebeln ins Fett und wird dann zugedeckt schonend gegart!\"  2. \"Der Schöpsenschlögel wird gesalzen und mit Zwiebeln in Fett bei niedriger Hitze sanft geschmort!\"  3. \"Die Hinterkeule des verschnittenen Hammels wird gesalzen, mit Zwiebeln in Fett angelegt und zugedeckt ganz langsam gedünstet!\""}]'::jsonb, ''),
  ('mei-liawa-klaana-schoaschi-leck-mi-doch-aum-oaschi', 'Mei liawa, klaana Schoaschi, leck mi doch aum Oaschi!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Mein lieber kleiner Schorschi, leck mich doch am Orschi!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Ach Schorschi, lieber Schorschi, du gehst mir g''sund aufs Orschi!\"  2. \"Lieber kleiner Schorschi mein, leck mich doch am Arsch ganz fein!\"  3. \"Mein süßer, kleiner Schorschi, geh mir nicht aufs Orschi!\""}]'::jsonb, ''),
  ('i-muass-mein-schoaschi-schoona-amoi-hiisetzn-nii-wiida-aufschdee', 'I muass mein Schoaschi schoona - amoi hiisetzn, nii wiida aufschdee!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich muss meinen Schorschi schonen - einmal hinsetzen, nie wieder aufstehen!', '[{"kategorie": "wörtlich", "text": "\"Ich muss mein Hinterteil schonen - einmal hinsetzen, nie wieder aufstehen!\"  2. \"Mein Schorschi muss geschont werden - drum steh ich erst wieder auf, wenn''s hier nichts mehr zu trinken gibt!\"  3. \"Mein Hintern streikt – aufgestanden wird erst, wenn die Getränke ausgehen!\""}]'::jsonb, ''),
  ('kinaeaesnessn-is-fia-mi-wia-schooda-mit-gatsch', 'Kinääsnessn is fia mi wia Schooda mit Gatsch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Chinesenessen ist für mich wie Schotter mit Gatsch!', '[{"kategorie": "wörtlich", "text": "\"Chinesisches Essen ist für mich wie ''ne Reislawine mit Soße!\"  2. \"Das Essen vom Chinesen ist nichts als [[Körndlzeug]] in brauner Sud!\"  3. \"[[Chinesenschotter]] mit Soße - das kriegst im Chinarestaurant!\""}]'::jsonb, ''),
  ('tritt-ned-aufn-schooda-dea-frissd-da-de-schuach', 'Tritt ned aufn Schooda - dea frissd da de Schuach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Tritt nicht auf den Schotter - der frisst dir die Schuhe!', '[{"kategorie": "wörtlich", "text": "\"Tritt da nicht rein, der Kies macht dir die Schuhe kaputt!\"  2. \"Bleib weg von dem Schutt, der ruiniert dir die Schuhe!\"  3. \"Geh da nicht drüber, das Geröll zerlegt dir die Sohlen!\""}]'::jsonb, ''),
  ('kaunnst-ma-den-schooda-wechsln', 'Kaunnst ma den Schooda wechsln?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kannst du mir den Schotter wechseln?', '[{"kategorie": "wörtlich", "text": "\"Kannst du mir das ganze Kleingeld wechseln?\"  2. \"Kannst du mir das Münzgeld in Banknoten wechseln?\"  3. \"Kannst du mir den Kleinscheiß in Papiergeld wechseln?\""}]'::jsonb, ''),
  ('waunn-gschoodad-is-haum-de-klimakleewa-in-aufdraadn', 'Waunn gschoodad is, haum de Klimakleewa in Aufdraadn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn geschottert ist, haben die Klimakleber den Aufgedrehten!', '[{"kategorie": "wörtlich", "text": "\"Wenn geschottert ist, haben die Klimakleber das Nachsehen!\"  2. \"Ist alles geschottert, bleibt für die Klimakleber nichts mehr, wo sie sich ankleben können!\"  3. \"Wenn geschottert ist, sind die Klimakleber aufgeschmissen!\""}]'::jsonb, 'in Aufdraadn haum'),
  ('gschdoodad-voi', 'gschdoodad voi', '', '', '', 'Grundwortschatz Wienerisch', 'geschottert voll', '[{"kategorie": "wörtlich", "text": "\"zum Bersten voll\""}, {"kategorie": "", "text": "\"gerammelt voll\""}, {"kategorie": "", "text": "\"rappelvoll\""}, {"kategorie": "", "text": "[[bummvoi]], [[grammäd]] voi, [[gschdeckd]] voi, [[gschdrotzd]] voi, [[gschdopfd]] voi"}]'::jsonb, ''),
  ('des-stadion-woa-gschoodad-voi-bis-zum-auschloog-kaa-quadratzentimaeaeta-frei', 'Des Stadion woa gschoodad voi bis zum Auschloog - kaa Quadratzentimääta frei!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das Stadion war geschottert voll bis zum Anschlag - kein Quadratzentimeter frei!', '[{"kategorie": "wörtlich", "text": "\"Das Stadion war gerammelt voll bis zum Anschlag - kein Quadratzentimeter frei!\"  2. \"Das Stadion platzte aus allen Nähten - da war kein [[Fleckerl]] mehr frei!\"  3. \"Das Stadion war bis zum Bersten gefüllt - da ging nichts mehr, absolut am Limit!\""}]'::jsonb, 'gschdoodad voi'),
  ('noochn-aufschdee-brauch-i-an-gschoodadn-sunst-kumm-i-ned-ind-gaeng', 'Noochn Aufschdee brauch I an Gschoodadn, sunst kumm I ned ind Gäng!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Nach dem Aufstehen brauch ich einen ''Geschotterten'', sonst komm'' ich nicht in die Gänge!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Aufstehen brauch ich einen [[Großen]] Schwarzen mit Rum, sonst komme ich nicht in die Gänge!\"  2. \"Nach dem Aufstehen brauch ich einen doppelten Mokka mit Rum, sonst werd ich nicht wach!\"  3. \"Ich brauch gleich in der Früh einen doppelten Schwarzen mit Rum, sonst geht bei mir gar nix!\""}]'::jsonb, ''),
  ('de-gschroppn-schoodan-duachs-schdianghaus-ois-waard-da-teifae-hinta-eana-hea', 'De Gschroppn schoodan duachs Schdianghaus, ois waard da Teifä hinta eana hea!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Gschrappen schottern durchs Stiegenhaus, als wäre der Teufel hinter ihnen her!', '[{"kategorie": "wörtlich", "text": "\"Die Kinder stürmen polternd durchs Stiegenhaus, als wäre der Teufel hinter ihnen her!\"  2. \"Die Kinder preschen lärmend durchs Stiegenhaus, als gäb’s kein Morgen!\"  3. \"Die Kinder schossen wie wild durchs Stiegenhaus, als würd''s irgendwo brennen!\""}]'::jsonb, ''),
  ('dea-kummd-daheagschoodad-wiara-daumpflok', 'Dea kummd daheagschoodad wiara Daumpflok!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der kommt dahergeschottert wie eine Dampflok!', '[{"kategorie": "wörtlich", "text": "\"Der kommt angerauscht wie eine Dampflok!\"  2. \"Der kommt angerollt wie eine Dampfwalze!\"  3. \"Der kommt mit derartigem Getöse angerannt, als wär er auf der Flucht!\""}]'::jsonb, ''),
  ('den-weg-den-wea-ma-aa-noo-schoodan', 'Den Weg den wea ma aa noo schoodan!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Diesen Weg werden wir auch noch schottern!', '[{"kategorie": "wörtlich", "text": "\"Diesen Weg werden wir auch noch mit Schotter befestigen!\"  2. \"Den Weg werden wir ebenfalls kiesen!\"  3. \"Den Weg werden wir auch noch mit Kies aufschütten und tragfähig machen!\""}]'::jsonb, ''),
  ('dea-kinaeaesnschooda-bleibt-ma-in-da-pappn-pickn', 'Dea Kinääsnschooda bleibt ma in da Pappn pickn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Chinesenschotter bleibt mir in der Pappen picken!', '[{"kategorie": "wörtlich", "text": "\"Dieser Rundkornschotter aus Fernost bleibt mir im Mund kleben!\"  2. Dieser asiatische Schotter pappt mir zwischen den Zähnen!  3. Der Reis klebt wie Kaugummi an meinem Gaumen!"}]'::jsonb, ''),
  ('waunn-i-schrammaemusik-hea-wiad-ma-waach-ums-heaz', 'Waunn I Schrammämusik hea, wiad ma waach ums Heaz!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wenn ich Schrammelmusik höre, wird mir weich ums Herz!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich Schrammelmusik höre, geht mir das Herz auf!\"  2. Wenn Schrammelmusik erklingt, schmilzt mein Herz dahin!  3. Wenn ich Schrammelmusik höre, singt mein Herz wie von selbst mit!"}]'::jsonb, ''),
  ('de-schrammaen', 'De Schrammän', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Die Schrammeln', '[{"kategorie": "wörtlich", "text": "\"Die Gebrüder Schrammel\" (vier musizierende Brüder, die als Quartett die Heurigenmusik Mitte des 19. Jahrhunderts in Wien salonfähig machten);  2.(allg.) \"Wiener Heurigenmusik in der Tradition der Gebrüder Schrammel\" (klassische Besetzung: zwei Geigen, eine Kontragitarre und eine Klarinette bzw. Harmonika), \"Volksmusikquartett in der Tradition von Johann und Josef Schrammel\", [[Schrammelquartett]]"}]'::jsonb, 'Waunnd Schrammän aufschbüün, is de Hittn voi!'),
  ('waunnd-schrammaen-aufschbueuen-is-de-hittn-voi', 'Waunnd Schrammän aufschbüün, is de Hittn voi!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Wenn die Schrammeln aufspielen, ist die Hütte voll!', '[{"kategorie": "wörtlich", "text": "\"Wenn die Musik der Gebrüder Schrammel erklingt, bleibt kein Sessel im Wirtshaus leer!\"  2. Sobald ein [[Schrammelquartett]] aufspielt, füllt sich das Wirtshaus bis auf den letzten Platz!  3. Bei der Musik der Schrammeln sitzt ganz Wien im Wirtshaus!"}]'::jsonb, 'De Schrammän'),
  ('ka-heiricha-is-komplett-oone-a-gscheids-schrammaequartett', 'Ka Heiricha is komplett oone a gscheids Schrammäquartett!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Kein Heuriger ist komplett ohne ein g''scheit''s Schrammelquartett!', '[{"kategorie": "wörtlich, Scherzreim", "text": "\"Kein Heuriger ist was wert ohne Schrammelkonzert!\"  2. Ohne ein gestandenes Schrammelquartett ist ''ne Wiener Weinschank nicht komplett!  3.  Ein Heuriger ohne Schrammelquartett ist wie ein [[Gespritzter]] ohne Wein!"}]'::jsonb, ''),
  ('des-breedl-liigd-schreams-so-passd-des-nii', 'Des Breedl liigd schreams - so passd des nii!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Brett liegt ganz schrems - so passt das nie!', '[{"kategorie": "wörtlich", "text": "\"Das Brett liegt schief, so passt das nie!\"  2. \"Das Brett liegt nicht gerade - so geht sich das nie aus!\"  3. \"Das Brett liegt aus der Flucht - so wird das nie was!\""}]'::jsonb, ''),
  ('dea-woid-ma-schreams-kumma-owa-ned-mit-mia', 'Dea woid ma schreams kumma - owa ned mit mia!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der wollte mir schrems kommen - aber nicht mit mir!', '[{"kategorie": "wörtlich", "text": "\"Der wollte mir von hintenrum kommen, aber da hat er Pech gehabt!\"  2. \"Der hat versucht, mich ums Eck herum zu erwischen – aber nicht mit mir!\"  3. \"Er wollte mich über Umwege ausmanövrieren - aber ohne Erfolg!\""}]'::jsonb, ''),
  ('da-goodan-schdeed-schreamsad-seit-da-schduam-driiwazoong-is', 'Da Goodan schdeed schreamsad, seit da Schduam driiwazoong is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Gadern steht schremsert, seit der Sturm darübergezogen ist!', '[{"kategorie": "wörtlich", "text": "\"Der Zaun steht windschief, seit der Sturm darübergezogen ist!\"  2. \"Das Gatter ist völlig verzogen, seit der Sturm da reingefahren ist!\"  3. \"Der Sturm hat den ganzen Zaun schiefgelegt!\""}]'::jsonb, ''),
  ('schreamsad-brauchsd-ma-ned-kumma-sunst-woas-des-fia-di', 'Schreamsad brauchsd ma ned kumma, sunst woas des fia di!', '', '', '', 'Wiener Gaunersprache', 'Schremsert brauchst du mir nicht zu kommen, sonst war''s das für dich!', '[{"kategorie": "wörtlich", "text": "\"Durch die Hintertür brauchst du mir nicht zu kommen, sonst war''s das für dich!\"  2. \"Hintenrum brauchst du''s bei mir erst gar nicht versuchen, denn sonst bist draußen!\"  3. \"Komm mir nur ja nicht von hinten, sonst bist du Geschichte!\""}]'::jsonb, ''),
  ('wea-iwad-schreamsn-geed-is-schnoella-dahaam', 'Wea iwad Schreamsn geed, is schnölla dahaam!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer über die Schremsen geht, ist schneller daheim!', '[{"kategorie": "wörtlich", "text": "\"Wer die Kurve abkürzt, ist schneller daheim!\"  2. \"Wer quer drüber statt außenrum geht, spart Zeit!\"  3. \"Wer querfeldein statt den langen Bogen geht, ist früher zu Hause!\""}]'::jsonb, ''),
  ('iwad-schreamsn', 'iwad Schreamsn', '', '', '', 'Grundwortschatz Wienerisch', 'über die Schremsen', '[{"kategorie": "wörtlich", "text": "\"über die Schräge\" (vom mittelhochdeutschen \"schræme\"=\"Schräge\")"}, {"kategorie": "allg.", "text": "\"die Kurve schneidend\", \"quer drüber\", \"querfeldein\", \"abseits der Wege\", \"quer durch die Landschaft\""}, {"kategorie": "", "text": "\"quer drüber\", \"ums Eck\", \"übers Eck\", \"schräg\", \"diagonal\""}, {"kategorie": "fig.", "text": "\"ums Eck herum\", auf Umwegen, hintenherum, \"durch die Hintertür\""}, {"kategorie": "scherzhaft für", "text": "\"über den Daumen\", \"ungefähr\", \"in etwa\", \"Pi mal Daumen\", [[schätzomativ]]"}]'::jsonb, 'Wea iwad Schreamsn geed, is schnölla dahaam!'),
  ('wia-san-aafoch-iwad-schreamsn-grennd-waeu-ma-kaa-zeid-mea-ghhobd-haum', 'Wia san aafoch iwad Schreamsn grennd, wäu ma kaa Zeid mea ghhobd haum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir sind einfach über die Schremsen gerannt, weil wir keine Zeit mehr hatten!', '[{"kategorie": "wörtlich", "text": "\"Wir sind einfach querfeldein gerannt, weil wir keine Zeit mehr zu verlieren hatten!\"  2. \"Wir haben abgekürzt und sind durchs Gelände gerannt, weil keine Zeit mehr war!\"  3. \"Wir sind quer übers Feld gerannt, weil jede Sekunde gezählt hat!\""}]'::jsonb, 'iwad Schreamsn'),
  ('neeman-kostn-iwad-schreamsn-daunn-troogda-si-leichta', 'Neeman Kostn iwad Schreamsn, daunn troogda si leichta!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Nehmen wir den Kasten über die Schremsen, dann trägt er sich leichter!', '[{"kategorie": "wörtlich", "text": "\"Nehmen wir den Kasten quer drüber, dann trägt er sich leichter!\"  2. \"Greifen wir uns den Kasten übers Eck, dann ist’s weniger Schlepperei!\"  3. \"Nehmen wir den Kasten diagonal statt gerade, dann lässt er sich leichter bewegen!\""}]'::jsonb, 'iwad Schreamsn'),
  ('kumma-nua-joo-ned-iwad-schreamsn-sunst-kaunnsd-da-jetzd-schoo-dein-groobschdaa-beschdoeoen', 'Kumma nua joo ned iwad Schreamsn, sunst kaunnsd da jetzd schoo dein Groobschdaa beschdöön!', '', '', '', 'Wiener Gaunersprache', 'Komm mir nur ja nicht über die Schremsen, sonst kannst du dir jetzt schon deinen Grabstein bestellen!', '[{"kategorie": "wörtlich", "text": "\"Komm mir nur ja nicht von hintenrum, sonst kannst du dir jetzt schon deinen Grabstein bestellen!\"  2. \"Komm mir nur ja nicht ums Eck herum, sonst bist du erledigt!\"  3. \"Komm mir nur ja nicht durch die Hintertür – ein falscher Zug, und du bist Geschichte!\""}]'::jsonb, ''),
  ('iwad-schreamsn-hauma-mit-dem-bruuch-fuffzg-mille-reewach-gmochd', 'Iwad Schreamsn hauma mit dem Bruuch fuffzg Mille Reewach gmochd!', '', '', '', 'Wiener Gaunersprache', 'Über die Schremsen haben wir mit dem Bruch fünfzig Mille Reibach gemacht!', '[{"kategorie": "wörtlich", "text": "\"Über den Daumen gerechnet haben wir mit diesem Einbruch fünfzigtauzsend Euro Reibach gemacht!\"  2. \"Pi mal Daumen hat uns dieser Einbruch fünfzigtausend Euro Gewinn eingebracht!\"  3. \"Ohne viel Rechnerei sind’s um die fünfzig Riesen Gewinn - und das mit nur einem Einbruch!\""}]'::jsonb, 'iwad Schreamsn'),
  ('tua-ned-schualn', 'Tua ned schualn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Tu nicht schurlen!', '[{"kategorie": "wörtlich", "text": "\"Hetz dich nicht so!\"  2. Lass dir ruhig Zeit!  3. Nicht so hastig!  4. Mach''s ordentlich, nicht überstürzt!"}]'::jsonb, ''),
  ('dea-schuald-umanaund-ois-haeda-a-wepsnnest-im-puedschama', 'Dea schuald umanaund, ois häda a Wepsnnest im Püdschama!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schurlt herum, als hätte er ein Wepsennest im Pyjama!', '[{"kategorie": "wörtlich", "text": "\"Der schwirrt herum, als hätte er ein Wespennest im Pyjama!\"  2. Der flitzt herum, als hätte er einen Bienenschwarm im Nacken!  3. Der wuselt herum, als hätte er Strom in den Socken!"}]'::jsonb, ''),
  ('a-schweednbombn-is-wiara-schaumbussi-leichd-siass-und-vagaenglich', 'A Schweednbombn is wiara Schaumbussi - leichd, siass und vagänglich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Eine Schwedenbombe ist wie ein Schaumbussi – leicht, süß und vergänglich!', '[{"kategorie": "wörtlich", "text": "\"Eine Schwedenbombe ist wie ein Kuss aus Schaum – leicht, süß und schnell weg!\"  2. Die Schwedenbombe ist wie ein süßer Kuss aus Schoko und luftigem Schaum – verführerisch flüchtig!  3. Die Schwedenbombe ist Schaum mit Schale und Seele – das ist nicht bloß eine Süßigkeit, das ist Wiener Lebensgefühl!"}]'::jsonb, ''),
  ('a-gulasch-und-a-seital-bia-des-is-mei-taeglichs-leebnselexiia', 'A Gulasch und a Seital Bia, des is mei täglichs Leebnselexiia!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Gulasch und ein Seiterl Bier, das ist mein tägliches Lebenselexier!', '[{"kategorie": "wörtlich, Spaßreim", "text": "\"Ein Gulasch und ein kleines Glas Bier - das ist mein tägliches Lebenselexier!\"  2. \"Ein Gulasch und dazu ein kleines Bier – so sieht''s aus, mein Lebenselexier!\"  3. \"Ein Teller Gulasch und ein kleines Bier – das ist und bleibt mein Lebenselixier!\""}]'::jsonb, ''),
  ('sekiia-mi-ned', 'Sekiia mi ned!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sekkier mich nicht!', '[{"kategorie": "wörtlich", "text": "\"Nerv mich nicht!\"  2. \"Hör auf, mich zu quälen!\"  3. \"Belästige mich nicht!\"  4. [[Gee ma ned aum Oasch!]]"}]'::jsonb, ''),
  ('gee-ma-ned-aum-oasch', 'Gee ma ned aum Oasch!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Geh mir nicht am Arsch!', '[{"kategorie": "wörtlich", "text": "\"Nerv mich nicht!\"  2. \"Hör auf, mich zu quälen!\"  3. \"Geh mir nicht auf den Sack!\"  4. [[Sekia mi ned!]]"}]'::jsonb, 'Sekiia mi ned!'),
  ('i-hoit-de-sekiirarei-von-meina-oidn-nimma-aus-de-stressd-mi-sogoa-im-schloof', 'I hoit de Sekiirarei von meina Oidn nimma aus - de stressd mi sogoa im Schloof!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich halt'' die Sekkiererei von meiner Alten nicht mehr aus - die stresst mich sogar im Schlaf!', '[{"kategorie": "wörtlich", "text": "\"Ich halte das ständige Genörgel meiner Frau nicht mehr aus – die nervt mich sogar im Schlaf!\"  2. \"Ich ertrag die Dauerbelästigung meiner Frau nicht mehr – die verfolgt mich bis in meine Träume!\"  3. \"Ich halte die endlose Nerverei meiner Frau nicht mehr aus – selbst im Schlaf verfolgt sie mich!\""}]'::jsonb, ''),
  ('wem-bis-aufs-bluad-sekiian', 'wem bis aufs Bluad sekiian', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden bis aufs Blut sekkieren', '[{"kategorie": "wörtlich", "text": "\"jemanden zu Tode nerven\""}, {"kategorie": "", "text": "\"jemanden bis zur Weißglut treiben\""}, {"kategorie": "", "text": "\"jemanden bis zum Äußersten reizen\""}, {"kategorie": "", "text": "\"jemanden bis aufs Letzte drangsalieren\""}]'::jsonb, 'Mei Oide sekiiad mi bis aufs Bluad - do kaunnsd jo nua noo saufn!'),
  ('mei-oide-sekiiad-mi-bis-aufs-bluad-do-kaunnsd-jo-nua-noo-saufn', 'Mei Oide sekiiad mi bis aufs Bluad - do kaunnsd jo nua noo saufn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Meine Alte sekkiert mich bis aufs Blut - da kannst du ja nur noch saufen!', '[{"kategorie": "wörtlich", "text": "\"Meine Frau nervt mich bis aufs Letzte – da wirst du zwangsläufig zum Trinker!\"  2. \"Meine Frau treibt mich bis zur Weißglut – da bleibt einem ja nur noch der Griff zum Glas!\"  3. \"Meine Alte drangsaliert mich rund um die Uhr – da muss man ja irgendwann zur Flasche greifen!\""}]'::jsonb, 'wem bis aufs Bluad sekiian'),
  ('de-sekaduua-von-mein-schaeaef-de-i-toogtaeglich-eaduidn-muass-ghead-eigentlich-extra-zoid', 'De Sekaduua von mein Schääf, de I toogtäglich eaduidn muass, ghead eigentlich extra zoid!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Sekkatur von meinem Chef, die ich tagtäglich Chef erdulden muss, gehört eigentlich extra bezahlt!', '[{"kategorie": "wörtlich", "text": "\"Die ständige Drangsalierung durch meinen Chef, die ich tagtäglich erdulden muss, gehört eigentlich extra bezahlt!\"  2. \"Das permanente Genörgel meines Chefs müsste ich mir eigentlich gesondert vergüten lassen!\"  3. \"Für die ständige Nerverei durch meinen Chef, die ich tagtäglich ertragen muss, sollte ich eigentlich eine Gehaltserhöhung verlangen!\""}]'::jsonb, ''),
  ('mia-soeoechn-in-schbeck-noo-wia-friara-iwa-buuchnhoiz', 'Mia sööchn in Schbeck noo wia friara iwa Buuchnhoiz!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wir selchen den Speck noch wie früher über Buchenholz!', '[{"kategorie": "wörtlich", "text": "\"Wir räuchern den Speck noch wie früher über Buchenholz!\"  2. \"Der Speck wird bei uns traditionell über Buchenholz geräuchert!\"  3. \"Wir machen den Speck auf alte Art im Buchenrauch haltbar!\""}]'::jsonb, ''),
  ('des-klassische-wiina-fruaschduck-san-zwa-semmaln-a-wiafae-butta-a-leffae-marmelaad-und-a-haeaefalkaffee', 'Des klassische Wiina Fruaschduck san zwa Semmaln, a Wiafä Butta, a Leffä Marmelaad und a Hääfalkaffee!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Das klassische Wiener Frühstück sind zwei Semmerln, ein Würfel Butter, ein Löffel Marmelade und ein Häferlkaffee!', '[{"kategorie": "wörtlich", "text": "\"Zum klassischen Wiener Frühstück gehören zwei Semmeln, Butter, Marmelade und ein Kaffee mit Schlag!\"  2. \"Ein typisches Wiener Frühstück besteht aus zwei Semmelchen mit Butter und Marmelade sowie einer Tasse Häferlkaffee!\"  3. \"In Wien beginnt der Tag traditionell mit zwei Semmerln, Butter, Marmelade und einem Milchkaffee!\""}]'::jsonb, ''),
  ('aum-semmal-sei', 'aum Semmal sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'am Semmerl sein', '[{"kategorie": "wörtlich", "text": "\"am Limit sein\" (Die Wendung stammt aus dem Arbeitsalltag: Wer nur noch ein Semmerl hat, ist am Tagesende, d.h. am Limit, die Kraft reicht nur mehr fürs Nötigste – danach ist Schluss. Daher die Bedeutung „völlig erschöpft sein“)"}, {"kategorie": "", "text": "\"am Ende seiner Kräfte sein\""}, {"kategorie": "", "text": "\"aus dem letzten Loch pfeifen\""}, {"kategorie": "", "text": "[[am Zahnfleisch gehen]]"}]'::jsonb, 'Finanziöö samma aum Semmal - de Reseawn san olle aufbrauchd!'),
  ('finanzioeoe-samma-aum-semmal-de-reseawn-san-olle-aufbrauchd', 'Finanziöö samma aum Semmal - de Reseawn san olle aufbrauchd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Finanziell sind wir am Semmerl - die Reserven sind alle aufgebraucht!', '[{"kategorie": "wörtlich", "text": "\"Finanziell sind wir am Limit, die Rücklagen sind alle aufgebraucht!\"  2. \"Finanziell pfeifen wir aus dem letzten Loch - unsere Reserven sind allesamt erschöpft!\"  3. \"Finanziell sind wir am Ende unserer Kräfte - es bestehen keine finanziellen Reserven mehr!\""}]'::jsonb, 'aum Semmal sei'),
  ('nooch-aana-hoibzeit-woa-ma-komplett-aum-semmal', 'Nooch aana Hoibzeit woa ma komplett aum Semmal!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Nach einer Halbzeit waren wir komplett am Semmerl!', '[{"kategorie": "wörtlich", "text": "\"Nach einer Halbzeit waren wir total am Limit!\"  2. \"Nach einer Spielhälfte waren wir am Ende unserer Kräfte!\"  3. \"Nach 45 Minuten haben wir aus dem letzten Loch gepfiffen!\""}]'::jsonb, ''),
  ('wea-im-wiina-kaffeehaus-broetchen-soogd-kriagd-viileichd-a-semmae-owa-nua-viileichd', 'Wea im Wiina Kaffeehaus ''Brötchen'' soogd, kriagd viileichd a Semmä - owa nua viileichd!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Wer im Wiener Kaffeehaus „Brötchen“ sagt, kriegt vielleicht ''ne Semmel – aber nur vielleicht!', '[{"kategorie": "wörtlich", "text": "\"Wer im Wiener Kaffeehaus nach einem Brötchen fragt, darf auf ''ne Semmel hoffen – mehr aber auch nicht!\"  2. \"Sag ''Brötchen'' im Kaffeehaus, und die Semmel is plötzlich keine Selbstverständlichkeit mehr!\"  3. \"Wer im Wiener Kaffeehaus ''Brötchen'' bestellt, muss darauf hoffen, dass der Ober gnädig ist!\""}]'::jsonb, ''),
  ('weggee-wia-de-woaman-semmaen', 'weggee wia de woaman Semmän', '', '', '', 'Wiener Sprüche, die sitzen!', 'weggehen wie die warmen Semmeln', '[{"kategorie": "wörtlich", "text": "\"reißenden Absatz finden\""}, {"kategorie": "", "text": "\"heiß begehrt sein\""}, {"kategorie": "", "text": "\"ein Verkaufsschlager sein\""}, {"kategorie": "", "text": "\"schnell ausverkauft sein\""}]'::jsonb, 'De Koatn san weggaunga wia de woaman Semmän - I hob grood noo an Plotz aum Juchää kriagd!'),
  ('de-koatn-san-weggaunga-wia-de-woaman-semmaen-i-hob-grood-noo-an-plotz-aum-juchaeae-kriagd', 'De Koatn san weggaunga wia de woaman Semmän - I hob grood noo an Plotz aum Juchää kriagd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Karten sind weggegangen wie die warmen Semmeln - ich hab grad noch einen Platz am Juchhe gekriegt!', '[{"kategorie": "wörtlich", "text": "\"Die Karten waren im Nu ausverkauft – ich habe gerade noch einen Platz auf dem obersten Rang bekommen!\"  2. \"Die Karten haben reißenden Absatz gefunden - mir blieb nur noch ein Platz in der obersten Galerie!\"  3. \"Die Nachfrage war enorm, ich habe nur noch einen der billigsten Plätze ergattert!\""}]'::jsonb, 'weggee wia de woaman Semmän'),
  ('semmaebreesln-suang-fiad-knusprige-hueuen-dee-a-jeeds-schnitzl-easchd-zua-legende-mochd', 'Semmäbreesln suang fiad knusprige Hüün, dee a jeeds Schnitzl easchd zua Legende mochd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Semmelbrösel sorgen für die knusprige Hülle, die jedes Schnitzel erst zur Legende macht!', '[{"kategorie": "wörtlich", "text": "\"Semmelbrösel sind das Herz jeder Panade – sie sorgen für die knusprige Hülle, die jedes Schnitzel erst zur Legende macht!\"  2. \"Semmelbrösel machen die Panade erst richtig knusprig – und das Schnitzel unvergesslich!\"  3. \"Semmelbrösel bilden die Seele jeder Panade und verleihen dem Schnitzel seine unvergleichliche Knusprigkeit!\""}]'::jsonb, ''),
  ('a-semmaehund-frissd-wos-do-is-und-passt-auf-wiara-haftlmocha', 'A Semmähund frissd, wos do is, und passt auf wiara Haftlmocha!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Ein Semmelhund frisst, was da ist, und passt auf wie ein Haftelmacher!', '[{"kategorie": "wörtlich", "text": "\"Ein semmelgelber Pinscher frisst, was da ist, und passt auf wie ein Schießhund!\"  2. \"Ein Ein österreichischer Pinscher frisst, was da ist, und wacht wie ein Luchs!\"  3. \"Ein Semmelpinscher frisst ohne Genierer, ist aber noch schneller beim Aufpassen!\""}]'::jsonb, ''),
  ('ois-semmaehund-bist-im-haeaefn-freiwueued', 'Ois Semmähund bist im Hääfn Freiwüüd!', '', '', '', 'Wiener Gaunersprache', 'Als Semmelhund bist du im Häfen Freiwild!', '[{"kategorie": "wörtlich", "text": "\"Als Schwuler bist du im Gefängnis vogelfrei!\"  2. \"Semmelhund im Knast heißt: jeden Tag Angst!\"  3. \"Als Homsexueller bist du im Zuchthaus kein Mensch mehr, sondern nur noch hilflose Beute!\""}]'::jsonb, ''),
  ('schdui-is-zum-scheissn-sessl-zum-sitzn', 'Schdui is zum Scheissn, Sessl zum Sitzn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Stuhl ist zum Scheißen, Sessel zum Sitzen!', '[{"kategorie": "wörtlich", "text": "\"Stuhl ist was fürs stille Örtchen, sitzen tut man auf einem Sessel!\"  2. \"Stuhl ist was fürs Klo - zum Sitzen brauchst du einen Sessel!\"  3. \"In Wien setzt man sich auf einen Sessel - den Stuhl entsorgt man am Häusl!\""}]'::jsonb, ''),
  ('bessa-a-sessl-ois-a-fleck', 'Bessa a Sessl ois a Fleck!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Besser ein Sessel als ein Fleck!', '[{"kategorie": "wörtlich, Schülerjargon", "text": "\"Besser ein Genügend als ein Nicht genügend!\"  2. \"Besser ein Zittervierer als ''ne Fünf!\"  3. \"Besser eine minus 4 als ein glatter [[Fetzen]]!\""}]'::jsonb, ''),
  ('schdott-dassa-hackld-sinniiada-in-gaunz-toog-iwan-sinn-von-seina-hockn', 'Schdott dassa hackld, sinniiada in gaunz Toog iwan Sinn von seina Hockn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Statt dass er hackelt, sinniert er den ganzen Tag über den Sinn seiner Hack''n!', '[{"kategorie": "wörtlich", "text": "\"Statt zu arbeiten, sinniert er den ganzen Tag über den Sinn seiner Arbeit!\"  2. \"Während andere hackeln, philosophiert er über den Zweck des Hackelns!\"  3. \"Er arbeitet nicht – er überlegt nur sehr gründlich, warum er arbeiten sollte!\""}]'::jsonb, ''),
  ('bei-dera-hitz-sauf-i-nua-sommagschbritzde-sunst-foid-ned-da-peegl-sondan-i', 'Bei dera Hitz sauf I nua Sommagschbritzde - sunst foid ned da Peegl, sondan I!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Bei dieser Hitze sauf'' ich nur Sommerg''spritzte - sonst fällt nicht der Pegel, sondern ich!', '[{"kategorie": "wörtlich", "text": "\"Bei der Hitze trinke ich nur Spritzwein mit deutlich mehr Sodawasser drin - sonst fällt nicht der Pegel, sondern ich!\"  2. \"Bei der Hitze saufe ich Spritzwein ganz stark verdünnt, sonst haut es mich schneller um, als mir lieb ist!\"  3. \"So heiß wie''s heute ist, gibt''s für mich nur [[Sommerspritzer]] oder nix – mehr Alkohol ist Selbstabschuss!\""}]'::jsonb, ''),
  ('sommaschbritza-kaunnsd-endlos-saufn-des-is-nua-mit-wei-vaduennts-wossa', 'Sommaschbritza kaunnsd endlos saufn - des is nua mit Wei vadünnts Wossa!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sommerspritzer kannst du endlos saufen - das ist nur mit Wein verdünntes Wasser!', '[{"kategorie": "wörtlich", "text": "\"Ein Sommerspritzer ist Wein mit doppelt so viel Sodawasser drinnen - den kannst du endlos saufen !\"  2. \"Sommerspritzer kannst trinken wie Wasser – da schwimmt der Wein nur mit!\"  3. \"Ein [[Sommerg]]''spritzter ist mehr Wasser als Wein und mehr Durstlöscher als Rausch!\""}]'::jsonb, ''),
  ('a-kaisaschbritza-is-da-kaisa-olla-schbritzweine', 'A Kaisaschbritza is da Kaisa olla Schbritzweine!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Ein Kaiserspitzer ist der Kaiser aller Spritzweine!', '[{"kategorie": "wörtlich", "text": "\"Der edelste aller Spritzweine ist der Kaiserspritzer!\"  2. Wenn’s ein Spritzer auf den Thron schafft, dann der Kaiserspritzer!  3. Der Kaiserspritzer ist die Krone in der Spritzwein-Monarchie!"}]'::jsonb, ''),
  ('im-reiskocha-gelingd-da-reis-oone-aubrennan-dageegn-is-reis-im-topf-a-reins-glicksschbueue', 'Im Reiskocha gelingd da Reis oone Aubrennan - dageegn is Reis im Topf a reins Glicksschbüü!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Im Reiskocher gelingt der Reis ohne Anbrennen - dagegen ist Reis im Topf ein reines Glücksspiel!', '[{"kategorie": "wörtlich", "text": "\"Im Reiskocher wird Reis perfekt – im Topf nur mit Glück!\"  2. \"Reis im Topf ist Nervensache, im Reiskocher ein Selbstläufer!\"  3. \"Der Reiskocher sorgt für gleichmäßige Ergebnisse – das Kochen im Topf ist deutlich fehleranfälliger!\""}]'::jsonb, ''),
  ('dea-reiskocha-schaud-aus-wiara-plastikschaas-auf-via-raadln-owa-liing-bliibm-isa-no-nii', 'Dea Reiskocha schaud aus wiara Plastikschaas auf via Raadln - owa liing bliibm isa no nii!', '', '', '', 'Wiener Mechaniker-Slang', 'Der Reiskocher schaut aus wie ein Plastikschas aufr vier Rädern - aber liegen geblieben ist er noch nie!', '[{"kategorie": "wörtlich", "text": "\"Dieser japanische Kleinwagen sieht aus wie Plastikschrott auf vier Rädern - aber liegen geblieben ist er noch nie!\"  2. \"Die Reisschüssel ist ''ne fahrende Plastikdose – aber zuverlässig wie ein Uhrwerk!\"  3. \"Der Reiskocher ist mehr Plastik als Auto – aber stehen geblieben ist er noch nie!\""}]'::jsonb, ''),
  ('reindlfrisua-geed-rumsdi-bumsdi-reindl-aufsetzn-rundumadum-schneidn-featig', 'Reindlfrisua geed rumsdi-bumsdi: Reindl aufsetzn, rundumadum schneidn – featig!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Reindlfrisur geht rumsti-bumsti: Reindl aufsetzen, rundherum schneiden - fertig!', '[{"kategorie": "wörtlich", "text": "\"Topffrisur geht rucki-zucki: Topf aufsetzen, rundherum schneiden - fertig!\"  2. \"Pilzkopf geht fix: Reindl drauf, einmal rundherum schneiden - fertig!\"  3. \"Pagenschnitt in Rekordzeit: Reindl drauf, Schnitt im Kreis – fertig!\""}]'::jsonb, ''),
  ('schau-da-den-sein-reindlschnitt-au-dea-rennd-umanaund-wiara-maxl-mit-leegohoeoem-nua-hoid-aus-hoa', 'Schau da den sein Reindlschnitt au - dea rennd umanaund wiara Maxl mit Leegohööm, nua hoid aus Hoa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Schau dir den Reindlschnitt von ihm an: Der rennt herum wie ein Maxl mit Legohelm, nur halt aus Haaren!', '[{"kategorie": "wörtlich", "text": "\"Schau dir den Topfschnitt von dem Kerl an: Der läuft herum wie ein Männlein mit Legohelm, nur eben aus Haaren!\"  2. \"Schau dir die [[Reindlfrisur]] von dem Typen an – der schaut aus wie ''ne Playmobilfigur mit Haarhelm!\"  3. \"Schau dir den Reindlschnitt an – der rennt herum wie ein Duplo-Manderl mit Haarpanzer!\""}]'::jsonb, ''),
  ('a-rindsbraadl-oone-sooss-is-wiara-schnitzl-oone-paniia-komplett-fian-oasch', 'A Rindsbraadl oone Sooss is wiara Schnitzl oone Paniia - komplett fian Oasch!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Rindsbratl ohne Soß ist wie ein Schnitzel ohne Panier - komplett für''n Arsch!', '[{"kategorie": "wörtlich", "text": "\"Ein Rindsbraten ohne Soße ist wie ein Schnitzel ohne Panade - total für''n Hugo!\"  2. \"Rindsbraten ohne Soße? Das ist wie ein Schnitzel ohne Panade: komplett daneben!\"  3. \"Ein Rindsbraten ohne Soße macht genauso wenig Sinn wie ein Schnitzel ohne Panade!\""}]'::jsonb, ''),
  ('waunnd-sooss-riind-waassd-dass-eanst-woa', 'Waunnd Sooss riind, waassd, dass eanst woa!', '', '', '', 'Wiener Gaunersprache', 'Wenn die Soße rinnt, weißt du, dass es ernst war!', '[{"kategorie": "wörtlich", "text": "\"Wenn Blut fließt, weißt du, dass es ernst war!\"  2. \"Wenn die Soße läuft, weiß jeder, es war kein Spaß!\"  3. \"Wenn s''Blut spritzt, wird klar, es war kein Kinderfasching!\""}]'::jsonb, ''),
  ('i-binds-braadl-imma-mid-an-schbogood-zsaumm-daunn-foid-beim-broodn-nix-ausaranaunda', 'I binds Braadl imma mid an Schbogood zsaumm - daunn foid beim Broodn nix ausaranaunda!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich binde den Braten immer mit einem Spagat zusammen - dann fällt beim Garen nichts auseinander!', '[{"kategorie": "wörtlich", "text": "\"Ich binde den Braten immer mit einem Bindfaden ab, damit er beim Garen seine Form behält!\"  2. \"Das Abbinden mit Spagat verhindert, dass der Braten beim Garen auseinanderfällt!\"  3. \"Vor dem Garen wird der Braten mit Spagat verschnürt, um eine gleichmäßige Form zu sichern!\""}]'::jsonb, ''),
  ('ea-hod-an-schbogood-probiad-dabei-haeaeds-eam-fost-in-beidl-oogrissn', 'Ea hod an Schbogood probiad - dabei hääds eam fost in Beidl oogrissn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Er hat einen Spagat probiert - dabei hat''s ihm fast den Beidl abgerissen!', '[{"kategorie": "wörtlich", "text": "\"Er hat einen Spagat versucht – dabei hat’s ihm fast alles zwischen den Beinen zerrissen!\"  2. \"Er hat einen Spreizschritt probiert - dabei hat''s ihm fast die Eier abgerissen!\"  3. \"Er hat den Spagat probiert – dabei hat er sich untenrum fast selbst entmannt!\""}]'::jsonb, ''),
  ('dea-schbogoodscheissa-mochd-aus-oim-a-bauschdoeoe', 'Dea Schbogoodscheissa mochd aus oim a Bauschdöö!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Dieser Spagatscheißer macht aus allem eine Baustelle!', '[{"kategorie": "wörtlich", "text": "\"Dieser Vollpfosten verwandelt jede Kleinigkeit in ein Chaos!\"  2. \"Mit dem Blindgänger wird jede Arbeit zur Dauerbaustelle!\"  3. \"Der Chaosmacher greift einmal hin, und schon ist alles im Eimer!\""}]'::jsonb, ''),
  ('de-schluchtnscheissa-haum-eana-gaunze-heimat-aun-d-marmelaadinga-vakaufd-goeoedgiirich-wias-san', 'De Schluchtnscheissa haum eana gaunze Heimat aun d''Marmelaadinga vakaufd - göödgiirich wias san!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Schluchtenscheißer haben ihre ganze Heimat an die Marmeladinger verkauft - geldgierig wie sie sind!', '[{"kategorie": "wörtlich", "text": "\"Die Tiroler haben ihre ganze Heimat an die [[Piefkes]] verkauft - und das aus reiner Profitgier!\"  2. \"Diese Alpenyetis haben ihre ganze Heimat an die Deutschen verscherbelt – Hauptsache, die Kasse stimmt!\"  3. \"Für Geld haben diese Hinterwäldler ihre ganze Heimat an die Piefkenäsen verkauft - am Schluss blieb nur Geld und kein Zuhause!\""}]'::jsonb, ''),
  ('du-schluchtnscheissa-du-vaknechada', 'Du Schluchtnscheissa, du vaknechada!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Du Schluchtenscheißer, du verknöcherter!', '[{"kategorie": "wörtlich", "text": "\"Du Alpen-Yeti, du rückständiger!\"  2. \"Du Hinterwäldler, du primitiver!\"  3. \"Du grobschlächtiger Bergbauer!\""}]'::jsonb, ''),
  ('gee-in-oasch-schbogoodscheissa', 'Gee in Oasch, Schbogoodscheissa!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Geh in den Arsch, Spagatscheißer!', '[{"kategorie": "wörtlich", "text": "\"Scher dich zum Teufel, du Blindgänger!\"  2. \"Verpiss dich, du Vollpfosten!\"  3. \"Fahr zur Hölle, du Pfeife!\""}]'::jsonb, ''),
  ('ea-hod-si-an-schbau-eizoong', 'Ea hod si an Schbau eizoong!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat sich einen Span eingezogen!', '[{"kategorie": "wörtlich", "text": "\"Er hat sich einen Holzsplitter eingezogen!\"  2. \"Ein [[Schiefer]] steckt unter seiner Haut!\"  3. \"Ein kleiner Splitter ist in seine Haut gedrungen!\""}]'::jsonb, ''),
  ('an-schbau-im-hian-haum', 'an Schbau im Hian haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Span im Hirn haben', '[{"kategorie": "wörtlich", "text": "\"einen Dachschaden haben\""}, {"kategorie": "", "text": "\"nicht ganz dicht sein;\"  3. [[einen Wurm in der Marille haben]]"}, {"kategorie": "", "text": "\"einen [[Titscher]] haben\""}, {"kategorie": "", "text": "\"einen [[Pascher]] haben\""}]'::jsonb, 'Host an Schbau im Hian, du Deppnschäädl?'),
  ('host-an-schbau-im-hian-du-deppnschaeaedl', 'Host an Schbau im Hian, du Deppnschäädl?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hast du einen Span im Hirn, du Deppenschädel?', '[{"kategorie": "wörtlich", "text": "\"Bist du nicht ganz dicht, du Vollidiot?\"  2. \"Hast du einen [[Pecker]] im Hirn, du Volltrottel?\"  3. [[Host an Wuam in da Marüün, du [[Beidl]]?]]"}]'::jsonb, 'an Schbau im Hian haum'),
  ('si-an-schbau-duachziang', 'si an Schbau duachziang', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich einen Span durchziehen', '[{"kategorie": "wörtlich", "text": "\"sich eine Zigarette reinziehen\""}, {"kategorie": "", "text": "\"einen tiefen Zug von der Zigarette machen\""}, {"kategorie": "", "text": "\"einen Lungenzug machen\""}]'::jsonb, ''),
  ('noochn-wickl-mit-seina-oidn-hod-a-si-easchd-amoi-an-schbau-duachzoong-um-de-neavn-zu-beruhign', 'Noochn Wickl mit seina Oidn hod a si easchd amoi an Schbau duachzoong, um de Neavn zu beruhign!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach dem Wickel mit seiner Alten hat er sich erst einmal einen Span durchgezogen, um die Nerven zu beruhigen!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Streit mit seiner Frau hat er sich erst mal eine Zigarette reingezogen, um die Nerven zu beruhigen!\"  2. \"Nach dem Krach mit seiner Alten nahm er erst mal einen ordentlichen Lungenzug, um wieder klar denken zu können!\"  3. \"Nach dem Zoff mit seiner Frau zog er tief an seiner Zigarette, um sich erst einmal zu sammeln!\""}]'::jsonb, 'si an Schbau duachziang'),
  ('reib-ume-an-schbau', 'Reib ume an Schbau!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Reib'' rüber ''nen Span!', '[{"kategorie": "wörtlich", "text": "\"Rück raus ''ne Zigarette!\"  2. \"Gib mir eine Zigarette!\"  3. \"Lass ''ne Zigarette rüberwachsen!\"  4. \"Hast du einen [[Tschick]] für mich?\""}]'::jsonb, ''),
  ('host-an-schbau-fia-mi', 'Host an Schbau fia mi?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hast du einen Span für mich?', '[{"kategorie": "wörtlich", "text": "\"Hast du eine Zigarette für mich?\"  2. \"Hast du einen [[Tschick]] für mich?\"  3. (Deutschland): \"Hast du ''ne Kippe für mich?\""}]'::jsonb, ''),
