  ('es-hoiz-lossd-si-nua-daunn-sauwa-schbaunln-waunns-trockn-is', 'Es Hoiz lossd si nua daunn sauwa schbaunln, waunns trockn is!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Holz lässt sich nur dann sauber späneln, wenn es trocken ist!', '[{"kategorie": "wörtlich", "text": "\"Das Holz lässt sich nur dann sauber in dünne Späne zerlegen, wenn es trocken ist!\"  2. \"Nur trockenes Holz gibt feine, gleichmäßige Späne!\"  3. \"Ist das Holz nicht trocken, lässt es sich nicht hauchdünn spalten!\""}]'::jsonb, ''),
  ('moch-kane-schbasettln', 'Moch kane Schbasettln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mach keine Spaßettln!', '[{"kategorie": "wörtlich", "text": "\"Lass die Späßchen!\"  2. \"Mach keine Faxen!\"  3. \"Schluss mit den Mätzchen!\"   4. \"Hör auf mit dem Unfug!\"  5. \"Schlag keine Kapriolen!\""}]'::jsonb, ''),
